"""
Consultation input model
------------------------
V1 intake: date of birth, exact time, place, and the planetary degrees for
Lagna + 9 grahas. Entered degrees are the AUTHORITATIVE input for the
interpretation engine; calculated positions are only ever used for comparison.
"""

# Generated by GitHub Copilot - Sep-27-2026

from __future__ import annotations

import datetime
import json
import re
from dataclasses import dataclass, field
from typing import Optional

from .planets import PLANET_NAMES, RASHI_NAMES

LAGNA_KEY = "Lagna"
BODY_KEYS = [LAGNA_KEY] + PLANET_NAMES   # Lagna, Surya, Chandra, ... Rahu, Ketu

# Accepted spellings for each rashi (Sanskrit, common variants, Western names).
_SIGN_ALIASES: dict[str, int] = {}
_ALIAS_TABLE = [
    (0,  ["mesha", "mesh", "aries", "ari", "ar"]),
    (1,  ["vrishabha", "vrishab", "vrsabha", "taurus", "tau", "ta"]),
    (2,  ["mithuna", "mithun", "gemini", "gem", "ge"]),
    (3,  ["karka", "kark", "kataka", "cancer", "can", "cn"]),
    (4,  ["simha", "sinha", "leo", "le"]),
    (5,  ["kanya", "virgo", "vir", "vi"]),
    (6,  ["tula", "thula", "libra", "lib", "li"]),
    (7,  ["vrishchika", "vrischika", "scorpio", "sco", "sc"]),
    (8,  ["dhanu", "dhanus", "sagittarius", "sag", "sa"]),
    (9,  ["makara", "makar", "capricorn", "cap", "cp"]),
    (10, ["kumbha", "kumbh", "aquarius", "aqu", "aq"]),
    (11, ["meena", "meen", "pisces", "pis", "pi"]),
]
for _idx, _names in _ALIAS_TABLE:
    for _n in _names:
        _SIGN_ALIASES[_n] = _idx


class InputError(ValueError):
    """Raised when a consultation input value cannot be understood."""


@dataclass
class EnteredPosition:
    """One manually supplied position, kept exactly as entered."""

    body: str
    longitude: float          # absolute sidereal longitude 0–360
    raw: str                  # original text, preserved for the record
    retrograde: bool = False

    @property
    def rashi_index(self) -> int:
        return int(self.longitude // 30) % 12

    @property
    def rashi(self) -> str:
        return RASHI_NAMES[self.rashi_index]

    @property
    def degree_in_rashi(self) -> float:
        return self.longitude % 30

    def formatted(self) -> str:
        deg = self.degree_in_rashi
        d = int(deg)
        m = int(round((deg - d) * 60))
        if m == 60:
            d, m = d + 1, 0
        retro = " ℞" if self.retrograde else ""
        return f"{self.rashi} {d:02d}° {m:02d}'{retro}"


# ── Degree parsing ────────────────────────────────────────────────────────────

_NUM = r"[0-9]+(?:\.[0-9]+)?"
_DMS_RE = re.compile(
    rf"^(?P<d>{_NUM})\s*(?:[°d:]\s*)?(?:(?P<m>{_NUM})\s*(?:['m:]\s*)?)?"
    rf"(?:(?P<s>{_NUM})\s*[\"s]?\s*)?$"
)


def _dms_to_degrees(text: str) -> float:
    """Parse '12', '12.5', '12°30', '12 30 15', \"12°30'15\\\"\" → decimal degrees."""
    cleaned = text.strip().replace("’", "'").replace("″", '"').replace("′", "'")
    match = _DMS_RE.match(cleaned)
    if not match:
        raise InputError(f"Cannot read degrees from '{text}'")
    d = float(match.group("d"))
    m = float(match.group("m") or 0.0)
    s = float(match.group("s") or 0.0)
    if m >= 60 or s >= 60:
        raise InputError(f"Minutes/seconds out of range in '{text}'")
    return d + m / 60.0 + s / 3600.0


def parse_position(body: str, text: str) -> EnteredPosition:
    """
    Parse an entered position. Accepted forms:
      "128.5"                    absolute sidereal longitude
      "Simha 8 30"               sign + degrees (+ minutes, seconds)
      "Simha 8°30'00\""          sign + DMS
      "8°30' Simha"              degrees before sign
      any of the above with a trailing 'R' / 'retro' marker
    """
    raw = (text or "").strip()
    if not raw:
        raise InputError(f"{body}: no value entered")

    working = raw
    retrograde = False
    retro_match = re.search(r"\b(r|retro|retrograde|℞)\b|℞", working, re.IGNORECASE)
    if retro_match:
        retrograde = True
        working = (working[:retro_match.start()] + working[retro_match.end():]).strip()

    sign_index: Optional[int] = None
    tokens = [t for t in re.split(r"[\s,]+", working) if t]
    remaining: list[str] = []
    for token in tokens:
        key = token.lower().strip(".")
        if sign_index is None and key in _SIGN_ALIASES:
            sign_index = _SIGN_ALIASES[key]
        else:
            remaining.append(token)

    if not remaining:
        raise InputError(f"{body}: no degree value in '{raw}'")

    value = _dms_to_degrees(" ".join(remaining))

    if sign_index is None:
        if not 0.0 <= value < 360.0:
            raise InputError(
                f"{body}: absolute longitude '{raw}' must be within 0–360°")
        longitude = value
    else:
        if not 0.0 <= value < 30.0:
            raise InputError(
                f"{body}: degree within {RASHI_NAMES[sign_index]} must be 0–30°, got {value:.4f}")
        longitude = sign_index * 30.0 + value

    if body in ("Rahu", "Ketu") and not retro_match:
        retrograde = True     # the nodes are always retrograde in motion

    return EnteredPosition(body=body, longitude=longitude, raw=raw,
                           retrograde=retrograde)


# ── Consultation input ────────────────────────────────────────────────────────

@dataclass
class ConsultationInput:
    """Everything the consultation form collects."""

    name: str
    dob: str                      # YYYY-MM-DD
    tob: str                      # HH:MM (24h), exact time of birth
    place: str
    positions: dict[str, EnteredPosition] = field(default_factory=dict)
    zodiac: str = "sidereal"      # entered degrees are sidereal unless stated
    ayanamsha: str = "Lahiri"
    notes: str = ""
    # Optional explicit geography. When present these override the city table,
    # which is how a birth place outside the built-in list is supplied.
    latitude: Optional[str] = None
    longitude: Optional[str] = None
    timezone_name: Optional[str] = None
    utc_offset: Optional[str] = None

    @property
    def has_entered_degrees(self) -> bool:
        return bool(self.positions)

    def birth_datetime(self) -> datetime.datetime:
        """Local birth date-time parsed from the form values."""
        try:
            return datetime.datetime.strptime(f"{self.dob} {self.tob}", "%Y-%m-%d %H:%M")
        except ValueError as exc:
            raise InputError(
                f"Date/time must be YYYY-MM-DD and HH:MM (got '{self.dob} {self.tob}')"
            ) from exc

    def missing_bodies(self) -> list[str]:
        return [b for b in BODY_KEYS if b not in self.positions]

    def require_complete(self):
        missing = self.missing_bodies()
        if missing:
            raise InputError("Missing entered degrees for: " + ", ".join(missing))

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "dob": self.dob,
            "tob": self.tob,
            "place": self.place,
            "latitude": self.latitude,
            "longitude": self.longitude,
            "timezone": self.timezone_name,
            "utc_offset": self.utc_offset,
            "zodiac": self.zodiac,
            "ayanamsha": self.ayanamsha,
            "notes": self.notes,
            "positions": {
                b: {"longitude": p.longitude, "raw": p.raw, "retrograde": p.retrograde}
                for b, p in self.positions.items()
            },
        }

    def print_entered(self):
        """Show the entered degrees exactly as the interpretation engine will use them."""
        print(f"\n  ENTERED DEGREES (authoritative — {self.zodiac}, {self.ayanamsha})")
        print(f"  {'Body':<10} {'Position':<24} {'Absolute':<12} As typed")
        print("  " + "─" * 74)
        for body in BODY_KEYS:
            pos = self.positions.get(body)
            if pos is None:
                print(f"  {body:<10} {'— not supplied —':<24}")
                continue
            print(f"  {body:<10} {pos.formatted():<24} {pos.longitude:>9.4f}°   {pos.raw}")


def positions_from_mapping(mapping: dict) -> dict[str, EnteredPosition]:
    """
    Build positions from a {body: value} mapping. Values may be strings
    ("Simha 8 30"), numbers (absolute degrees), or
    {"longitude": .., "retrograde": ..} objects.
    """
    positions: dict[str, EnteredPosition] = {}
    aliases = {b.lower(): b for b in BODY_KEYS}
    aliases.update({
        "ascendant": LAGNA_KEY, "asc": LAGNA_KEY, "lagna": LAGNA_KEY,
        "sun": "Surya", "moon": "Chandra", "mars": "Mangal",
        "mercury": "Budha", "jupiter": "Guru", "venus": "Shukra",
        "saturn": "Shani", "rahu": "Rahu", "ketu": "Ketu",
    })
    for key, value in mapping.items():
        body = aliases.get(str(key).strip().lower())
        if body is None:
            raise InputError(f"Unknown body '{key}' in degrees input")
        if isinstance(value, dict):
            if "longitude" not in value:
                raise InputError(f"{body}: object form requires 'longitude'")
            pos = parse_position(body, str(value["longitude"]))
            pos.retrograde = bool(value.get("retrograde", pos.retrograde))
            pos.raw = str(value.get("raw", pos.raw))
        else:
            pos = parse_position(body, str(value))
        positions[body] = pos
    return positions


def load_consultation_file(path: str) -> ConsultationInput:
    """Load a consultation form from JSON (see sample_consultation.json)."""
    with open(path, "r", encoding="utf-8") as fh:
        data = json.load(fh)
    if not isinstance(data, dict):
        raise InputError(f"{path}: expected a JSON object")
    def optional(*keys) -> Optional[str]:
        for key in keys:
            if data.get(key) not in (None, ""):
                return str(data[key])
        return None

    place = data.get("place")
    if place in (None, ""):
        # Never substitute a default city: the Lagna depends on it entirely.
        raise InputError(
            f"{path}: 'place' is required. Give a birth place, or supply "
            f"'latitude', 'longitude' and 'timezone' explicitly.")

    try:
        return ConsultationInput(
            name=str(data.get("name", "Unknown")),
            dob=str(data["dob"]),
            tob=str(data.get("tob") or data.get("time") or "12:00"),
            place=str(place),
            positions=positions_from_mapping(data.get("positions", {})),
            zodiac=str(data.get("zodiac", "sidereal")),
            ayanamsha=str(data.get("ayanamsha", "Lahiri")),
            notes=str(data.get("notes", "")),
            latitude=optional("latitude", "lat"),
            longitude=optional("longitude", "lon", "lng"),
            timezone_name=optional("timezone", "timezone_name", "tz"),
            utc_offset=optional("utc_offset", "utc_offset_at_birth", "offset"),
        )
    except KeyError as exc:
        raise InputError(f"{path}: missing required field {exc}") from exc


def prompt_positions(existing: Optional[dict[str, EnteredPosition]] = None
                     ) -> dict[str, EnteredPosition]:
    """Interactively collect degrees for Lagna and the nine grahas."""
    print("\n  Enter degrees — e.g. 'Simha 8 30', \"8°30' Simha\", or '128.5'")
    print("  Add 'R' for retrograde. Press Enter to skip a body.\n")
    positions: dict[str, EnteredPosition] = dict(existing or {})
    for body in BODY_KEYS:
        label = "Ascendant (Lagna)" if body == LAGNA_KEY else body
        while True:
            answer = input(f"  {label:<20}: ").strip()
            if not answer:
                break
            try:
                positions[body] = parse_position(body, answer)
                break
            except InputError as exc:
                print(f"    ✗ {exc}")
    return positions
